const stack = [];
function use(fn) { stack.push(fn); }
function run(ctx, final) {
  let i = 0;
  function next(err) {
    while (i < stack.length) {
      const mw = stack[i];
      if (err) {
        if (mw.length === 4) { i++; mw(err, ctx, {}, next); return; }
        i++; continue;
      }
      if (mw.length === 4) { i++; continue; }
      i++;
      try {
        const r = mw(ctx, next);
        if (r && typeof r.then === 'function') r.catch(e => next(e));
      } catch (e) { next(e); }
      return;
    }
    if (err) { ctx.log.push('UNHANDLED:' + err.message); return; }
    final(ctx);
  }
  next();
}
